const t="bibcleaner-selection";chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.removeAll(()=>{chrome.contextMenus.create({id:t,title:"Clean or verify BibTeX",contexts:["selection"]})})});chrome.contextMenus.onClicked.addListener(async e=>{if(e.menuItemId!==t||!e.selectionText)return;const n=e.selectionText.slice(0,5e6);await chrome.storage.session.set({pendingSelection:{text:n,at:Date.now()}}),await chrome.tabs.create({url:chrome.runtime.getURL("popup/index.html?view=tab&source=selection")})});
